(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-989":{scenario:{company:"Mây Bạc Airlines",supervisor:{name:"Trần Hữu Phước",role:{vi:"Trưởng ca Trung tâm Điều hành Khai thác",en:"OCC Duty Manager"}},ref_code:"OFP-7215",title:{vi:"Sân bay dự bị dùng được. Nhiên liệu đủ luật. Không đánh đổi an toàn.",en:"A usable alternate. Legal fuel. No trade-off on safety."},brief:{vi:"Chuyến bay 215 đi XKHA. TAF của sân bay dự bị gần nhất XKMB có TEMPO trần mây 200 ft, tầm nhìn 800 m trong khung giờ đến dự kiến; XKLA dự báo tốt. Số liệu kế hoạch: taxi 200 kg, nhiên liệu chuyến 5400 kg, dự phòng cuối 30 phút 1100 kg; nhiên liệu đi dự bị XKMB 1150 kg, XKLA 1650 kg. Bản nháp OFP-7215 chọn XKMB và nhiên liệu tại cửa 8120 kg. Đối chiếu OFP đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"Flight 215 is bound for XKHA. The TAF for the nearest alternate XKMB has a TEMPO of 200 ft ceiling and 800 m visibility in the ETA window; XKLA is forecast good. Planning data: taxi 200 kg, trip fuel 5400 kg, 30-minute final reserve 1100 kg; alternate fuel to XKMB 1150 kg, to XKLA 1650 kg. Draft OFP-7215 selects XKMB with block fuel of 8120 kg. Compare it with the approved OFP, correct both fields and write an evidence-based report."},reference_title:{vi:"Kế hoạch bay khai thác (OFP) đã duyệt · OFP-7215",en:"Approved operational flight plan · OFP-7215"},fields:[{id:"DEST_ALT",label:{vi:"Sân bay dự bị đích đến",en:"Destination alternate"},initial:"XKMB",expected:"XKLA",choices:["XKMB","XKLA","XKHA"],reference:"OFP đã duyệt - mục sân bay dự bị",hint:{vi:"Theo chính sách của hãng (mô phỏng), sân bay dự bị có TEMPO dưới tiêu chuẩn lập kế hoạch trong khung giờ đến thì không được chọn.",en:"Under the airline policy (training), an alternate with a TEMPO below planning minima in the ETA window may not be selected."}},{id:"BLOCK_FUEL",label:{vi:"Nhiên liệu tối thiểu tại cửa (kg)",en:"Minimum block fuel (kg)"},initial:"8120",expected:"8620",reference:"Bảng tính nhiên liệu OFP",ref_value:{vi:"Taxi 200; chuyến 5400; dự phòng chặng 5% nhiên liệu chuyến; dự bị XKLA 1650; dự phòng cuối 1100 (kg)",en:"Taxi 200; trip 5400; contingency 5% of trip; alternate XKLA 1650; final reserve 1100 (kg)"},hint:{vi:"Nhiên liệu dự bị phải tính tới sân bay dự bị đã chọn đúng; dự phòng chặng tính trên nhiên liệu chuyến.",en:"Alternate fuel must be to the correctly selected alternate; contingency is a share of trip fuel."}}],sop32:{vi:"Nhiên liệu tối thiểu tại cửa = taxi + nhiên liệu chuyến + dự phòng chặng (5% nhiên liệu chuyến) + nhiên liệu đi dự bị đích + dự phòng cuối 30 phút + nhiên liệu thêm (bài này bằng 0).",en:"Minimum block fuel = taxi + trip fuel + contingency (5% of trip) + destination alternate fuel + 30-minute final reserve + extra fuel (zero here)."},context:{label:"OFP / OFP-7215",metrics:[{label:{vi:"Nhiên liệu chuyến",en:"Trip fuel"},value:"5,400 kg"},{label:{vi:"Dự phòng cuối 30 phút",en:"Final reserve 30 min"},value:"1,100 kg"},{label:{vi:"Đi dự bị XKMB / XKLA",en:"Alternate XKMB / XKLA"},value:"1,150 / 1,650 kg"}]},crisis:{vi:"Phòng thương mại gọi: “Chọn XKMB đi cho nhẹ nhiên liệu, TEMPO thôi chắc không sao. Thêm 500 kg nhiên liệu là phải hạ 500 kg hàng của khách lớn, trưởng phòng đã hứa với họ rồi.”",en:"Commercial calls: “Plan XKMB to save fuel, it's only a TEMPO, it'll be fine. Another 500 kg of fuel means offloading 500 kg of a key customer's cargo, and the manager already promised them.”"},options:{safe:{vi:"Giữ XKLA và nhiên liệu tối thiểu 8620 kg, báo trưởng ca OCC và cơ trưởng, đề xuất hạ tải hàng theo thứ tự ưu tiên hoặc dừng kỹ thuật, ghi nhận áp lực vào báo cáo.",en:"Keep XKLA and the 8620 kg minimum, inform the OCC duty manager and the captain, propose offloading cargo by priority or a technical stop and record the pressure."},shortcut:{vi:"Chọn XKMB và giữ 8120 kg để chở đủ hàng như đã hứa.",en:"Plan XKMB with 8120 kg so all the promised cargo flies."},wait:{vi:"Để cơ trưởng tự quyết khi ra tàu, không cập nhật OFP.",en:"Leave it to the captain at the aircraft and do not update the OFP."}},questions:{vi:["Vì sao loại XKMB và chọn XKLA làm sân bay dự bị? Dữ liệu TAF nào chứng minh điều đó?","Trình bày cách tính nhiên liệu tối thiểu tại cửa và cách bạn xử lý yêu cầu ưu tiên hàng hóa của phòng thương mại."],en:["Why reject XKMB and select XKLA as the alternate? Which TAF data proves it?","Explain how you calculated minimum block fuel and how you handle Commercial's request to prioritise cargo."]},hints:{vi:["Đọc TAF của từng sân bay dự bị trong khung giờ đến dự kiến và so với tiêu chuẩn lập kế hoạch.","Cộng đủ các thành phần theo SOP mục 3.2, dự phòng chặng lấy 5% của nhiên liệu chuyến.","Đọc lại SOP mục 4.2: tải thương mại không bao giờ được ưu tiên hơn nhiên liệu tối thiểu theo quy định."],en:["Read each alternate's TAF for the ETA window and compare it with planning minima.","Add every component per SOP 3.2, with contingency at 5% of trip fuel.","Re-read SOP 4.2: commercial load never takes priority over regulatory minimum fuel."]}},learning:{summary:{vi:"Điều phái viên khai thác bay lập kế hoạch bay khai thác (OFP), tính nhiên liệu, chọn đường bay và sân bay dự bị, phân tích thời tiết, NOTAM, giới hạn trọng tải và theo dõi chuyến bay từ trung tâm điều hành khai thác (OCC). Cùng cơ trưởng chia sẻ trách nhiệm về quyết định khai thác, nghề đòi hỏi am hiểu quy định nhiên liệu, khí tượng hàng không, tính năng tàu bay và bản lĩnh giữ vững an toàn trước áp lực thương mại.",en:"A flight dispatcher prepares the operational flight plan (OFP), calculates fuel, selects routes and alternates, analyses weather, NOTAMs and weight limits and follows flights from the operations control centre (OCC). Sharing responsibility for operational decisions with the captain, the role requires knowledge of fuel rules, aviation weather and aircraft performance, and the resolve to keep safety first under commercial pressure."},responsibilities:{vi:["Lập kế hoạch bay, chọn đường bay, mực bay và sân bay dự bị phù hợp thời tiết, NOTAM.","Tính nhiên liệu theo chính sách nhiên liệu của hãng và quy định nhà chức trách.","Phân tích METAR, TAF, SIGMET, gió trên cao và thời tiết nguy hiểm trên đường bay.","Kiểm tra giới hạn trọng tải, hạng mục MEL ảnh hưởng khai thác và thông báo cho tổ lái.","Theo dõi chuyến bay, hỗ trợ tổ lái khi chuyển hướng, chậm chuyến hoặc tình huống bất thường."],en:["Plan flights, choosing routes, levels and alternates suited to weather and NOTAMs.","Calculate fuel under the airline fuel policy and authority rules.","Analyse METAR, TAF, SIGMET, upper winds and hazardous en-route weather.","Check weight limits and MEL items affecting operations and brief the crew.","Follow flights and support the crew during diversions, delays or abnormal events."]},competencies:[{name:{vi:"Lập kế hoạch nhiên liệu",en:"Fuel planning"},desc:{vi:"Tính đủ các thành phần nhiên liệu và cập nhật ngay khi đổi đường bay, sân bay dự bị.",en:"Compute every fuel component and update it as soon as routes or alternates change."}},{name:{vi:"Khí tượng hàng không",en:"Aviation meteorology"},desc:{vi:"Giải mã METAR, TAF, nhận diện nhóm TEMPO, BECMG, PROB và tác động tới tiêu chuẩn khai thác.",en:"Decode METAR and TAF, read TEMPO, BECMG and PROB groups and their effect on minima."}},{name:{vi:"Tính năng & trọng tải",en:"Performance & weight"},desc:{vi:"Kiểm tra giới hạn cất cánh, hạ cánh, trọng lượng tối đa và phân bổ tải hợp lệ.",en:"Check take-off and landing limits, maximum weights and valid load distribution."}},{name:{vi:"Theo dõi chuyến bay",en:"Flight following"},desc:{vi:"Giám sát tiến trình chuyến bay, nhiên liệu còn lại và cảnh báo sớm cho tổ lái.",en:"Monitor flight progress and remaining fuel and warn the crew early."}},{name:{vi:"Ra quyết định an toàn",en:"Safety decision making"},desc:{vi:"Giữ quyết định đúng quy định trước áp lực thương mại và ghi nhận minh bạch lý do.",en:"Hold compliant decisions under commercial pressure and record the reasons transparently."}}],knowledge:{vi:["Phụ lục 6 ICAO về yêu cầu nhiên liệu, sân bay dự bị và kiểm soát khai thác.","ICAO Doc 9976 hướng dẫn lập kế hoạch bay và quản lý nhiên liệu.","Mã thời tiết METAR, TAF và các nhóm thay đổi BECMG, TEMPO, PROB theo Phụ lục 3 ICAO.","Quy tắc khai thác tầm xa EDTO/ETOPS và yêu cầu sân bay dự bị trên đường bay.","Danh mục thiết bị tối thiểu (MEL) và tác động tới kế hoạch bay, nhiên liệu."],en:["ICAO Annex 6 on fuel requirements, alternates and operational control.","ICAO Doc 9976 on flight planning and fuel management.","METAR and TAF codes and the BECMG, TEMPO and PROB change groups under ICAO Annex 3.","EDTO/ETOPS extended range rules and en-route alternate requirements.","The minimum equipment list (MEL) and its effect on flight planning and fuel."]},tools:["Hệ thống lập kế hoạch bay","Phần mềm theo dõi chuyến bay","Cổng khí tượng hàng không","Hệ thống tra cứu NOTAM","Liên lạc dữ liệu ACARS"],kpis:{vi:["Tỷ lệ OFP đúng ngay lần đầu, không phải phát hành lại.","Chênh lệch giữa nhiên liệu kế hoạch và thực tế mỗi chuyến.","Số chuyến chuyển hướng do lập kế hoạch thiếu sót (mục tiêu bằng 0).","Thời gian phản hồi yêu cầu hỗ trợ của tổ lái."],en:["Right-first-time OFP rate with no reissue.","Difference between planned and actual fuel per flight.","Diversions caused by planning errors (target zero).","Response time to crew support requests."]},day:[{time:"06:00",vi:"Nhận bàn giao ca OCC, xem chuyến đang khai thác, hỏng hóc trì hoãn và NOTAM mới.",en:"Take the OCC handover and review active flights, deferred defects and new NOTAMs."},{time:"07:00",vi:"Phân tích thời tiết, chọn đường bay và sân bay dự bị cho các chuyến trong ca.",en:"Analyse weather and choose routes and alternates for the shift's flights."},{time:"09:00",vi:"Phát hành OFP và trao đổi với tổ lái về nhiên liệu, thời tiết.",en:"Release OFPs and brief crews on fuel and weather."},{time:"12:00",vi:"Theo dõi chuyến bay, xử lý yêu cầu chuyển hướng do thời tiết xấu.",en:"Follow flights and handle a weather diversion request."},{time:"14:00",vi:"Ghi nhật ký ca, báo cáo sự kiện và bàn giao ca sau.",en:"Complete the shift log, report events and hand over."}],mistakes:{vi:["Chọn sân bay dự bị gần nhất mà bỏ qua nhóm TEMPO dưới tiêu chuẩn trong khung giờ đến.","Tính dự phòng chặng trên tổng nhiên liệu hoặc quên cập nhật nhiên liệu khi đổi sân bay dự bị.","Cắt nhiên liệu dưới mức tối thiểu để ưu tiên hàng hóa theo yêu cầu thương mại."],en:["Choosing the nearest alternate while ignoring a TEMPO below minima in the ETA window.","Basing contingency on total fuel or not updating fuel after changing the alternate.","Cutting fuel below the minimum to favour cargo at Commercial's request."]},career:[{vi:"Trợ lý điều phái bay",en:"Assistant flight dispatcher"},{vi:"Điều phái viên khai thác bay có giấy phép",en:"Licensed flight dispatcher"},{vi:"Điều phái viên chính, trưởng ca OCC",en:"Senior dispatcher, OCC duty manager"},{vi:"Giám đốc trung tâm điều hành khai thác",en:"Head of operations control centre"}],glossary:[{term:"OFP",vi:"Kế hoạch bay khai thác gồm đường bay, mực bay, thời gian, nhiên liệu và sân bay dự bị.",en:"Operational flight plan with route, levels, times, fuel and alternates."},{term:"TAF",vi:"Bản tin dự báo thời tiết sân bay trong một khoảng thời gian xác định.",en:"Terminal aerodrome forecast for a defined period."},{term:"TEMPO",vi:"Nhóm biến đổi tạm thời trong TAF: mỗi lần dưới 1 giờ và tổng thời gian dưới một nửa thời kỳ dự báo.",en:"Temporary change group in a TAF: each spell under 1 hour, totalling less than half the period."},{term:"Contingency fuel",vi:"Nhiên liệu dự phòng chặng bù cho các yếu tố không lường trước, thường theo tỷ lệ nhiên liệu chuyến.",en:"Fuel for unforeseen factors, usually a percentage of trip fuel."},{term:"Final reserve fuel",vi:"Nhiên liệu dự phòng cuối cùng, với tàu phản lực tương ứng 30 phút bay chờ ở 1500 ft.",en:"Last reserve fuel, for jets equal to 30 minutes holding at 1500 ft."}],quiz:[{q:{vi:"Nhiên liệu chuyến 6000 kg, dự phòng chặng 5%. Dự phòng chặng là bao nhiêu?",en:"Trip fuel is 6000 kg and contingency is 5%. What is the contingency fuel?"},options:{vi:["600 kg","150 kg","500 kg","300 kg"],en:["600 kg","150 kg","500 kg","300 kg"]},answer:3,explain:{vi:"Dự phòng chặng = 5% x 6000 = 300 kg.",en:"Contingency = 5% x 6000 = 300 kg."}},{q:{vi:"Nhóm TEMPO trong TAF có nghĩa là gì?",en:"What does a TEMPO group in a TAF mean?"},options:{vi:["Thay đổi lâu dài và ổn định","Biến đổi tạm thời, mỗi lần dưới 1 giờ, tổng dưới nửa thời kỳ","Xác suất 30% xảy ra","Thời tiết đã quan trắc thực tế"],en:["A lasting, steady change","Temporary changes, each under 1 hour, totalling under half the period","A 30% probability","Actually observed weather"]},answer:1,explain:{vi:"TEMPO mô tả biến đổi tạm thời; khi dưới tiêu chuẩn tại sân bay dự bị phải được đánh giá theo chính sách của hãng.",en:"TEMPO describes temporary changes; when below minima at an alternate it must be assessed under the airline policy."}},{q:{vi:"Phòng thương mại đề nghị cắt nhiên liệu dưới mức tối thiểu để chở thêm hàng. Bạn làm gì?",en:"Commercial asks to cut fuel below the minimum to carry more cargo. What do you do?"},options:{vi:["Giữ nhiên liệu tối thiểu, báo trưởng ca và cơ trưởng, đề xuất hạ tải hàng","Đồng ý vì đường bay ngắn","Cắt một nửa phần chênh lệch","Để cơ trưởng tự xử lý"],en:["Keep minimum fuel, inform the duty manager and captain and propose offloading cargo","Agree because the sector is short","Cut half the difference","Leave it to the captain"]},answer:0,explain:{vi:"Nhiên liệu tối thiểu là yêu cầu an toàn bắt buộc; tải thương mại phải điều chỉnh theo nhiên liệu chứ không ngược lại.",en:"Minimum fuel is a mandatory safety requirement; payload must adjust to fuel, not the reverse."}},{q:{vi:"Dự phòng cuối cho tàu bay phản lực theo ICAO tương ứng với gì?",en:"Under ICAO, what does final reserve fuel for a jet correspond to?"},options:{vi:["10 phút bay bằng","60 phút bay đến sân bay dự bị","30 phút bay chờ ở 1500 ft trên sân bay ở điều kiện chuẩn","5% nhiên liệu chuyến"],en:["10 minutes of cruise","60 minutes to the alternate","30 minutes holding at 1500 ft above the aerodrome in standard conditions","5% of trip fuel"]},answer:2,explain:{vi:"Với tàu phản lực, dự phòng cuối là lượng nhiên liệu bay chờ 30 phút ở 1500 ft (450 m) trên sân bay.",en:"For jets, final reserve is the fuel to hold for 30 minutes at 1500 ft (450 m) above the aerodrome."}}],tools_en:["Flight planning system","Flight tracking software","Aviation weather portal","NOTAM lookup system","ACARS data link"]}}})})(window.KKR);
